--             "query": {
--           "bool": {
--         "should": [
--         {"match": {"query": "hi hello"}},
--       {"match": { "content": "oceanbase mysql" }}
--   ]
--
--   }
--
--   },
--   "knn" : {
--   "field": "vector",
--
--   "k": 5,
--
--   "query_vector": [1,2,3]
--
--   },
